def write(name, cols, rows):
    with open(HERE / name, "w", newline="") as f:
        w = csv.writer(f, delimiter="\t", lineterminator="\n")
        w.writerow(cols)
        for r in rows:
            w.writerow([r[c] for c in cols] if isinstance(r, dict) else r)


def main():
    if len(sys.argv) < 2 or sys.argv[1] != "write":
        print(__doc__)
        return
    for q in Q:
        assert q["disposition"] in DISPOSITIONS, q["disposition"]
        q["status_before"] = STATUS_BEFORE[q["proposal_id"]]
        q["status_after"] = q["status_before"]            # a disposition never changes the hand-over status
    write("qualification_it21_p4a.tsv", Q_COLS, Q)
    write("edge_provenance_it21_p4a.tsv", E_COLS, E)
    write("reading_depth_it21_p4a.tsv", D_COLS, D)
    write("locators_it21_p4a.tsv", L_COLS, L)
    write("status_after_it21_p4a.tsv", ["proposal_id", "compound", "status_before", "disposition", "status_after", "status_changed", "qualified"],
          [[q["proposal_id"], q["compound"], q["status_before"], q["disposition"], q["status_after"], "no", "no (needs a sourced role and a measured link in a WWOX system)"] for q in Q])
    recs = []
    for q in Q:
        st = STATE[q["disposition"]]
        dec = {"CONDITIONAL": "CONDITIONAL (kept; scope narrowed; role unknown)", "INCONCLUSIVE": "INCONCLUSIVE (insufficient support, not no activity)", "DROP": "DROP (informative; see reasons)", "KEEP": "KEEP"}[st]
        recs.append([q["cand_id"], "P4a-IT21", q["compound"], st, dec, "", CLASS[st], "generated_in_it21", NEED[q["proposal_id"]]])
    write("it21_p4a_records.tsv", R_COLS, recs)
    print("written", len(Q), "qualification rows,", len(E), "edge rows,", len(D), "reading rows,", len(L), "locators")


if __name__ == "__main__":
    main()
